と教えてもらえて、それだけで行きやすくなりました。当日も、この機械は何をするものか、いちいち説明してくださいます。\n\n化粧品を買わされるのではと思っていましたが、一度も勧められていません。&quot;},{&quot;name&quot;:&quot;A様&quot;,&quot;age&quot;:&quot;30代&quot;,&quot;job&quot;:&quot;会社員&quot;,&quot;photo&quot;:&quot;https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/staff_03.webp&quot;,&quot;alt&quot;:&quot;30代の方&quot;,&quot;excerpt&quot;:&quot;友人に紹介されて来ました。紹介したくなる理由が分かりました。&quot;,&quot;text&quot;:&quot;友人に紹介されて来ました。\n\n「安いから」でも「効くから」でもなく、「話しやすいから」と言われて来たのですが、来てみて分かりました。こちらが黙っていたい日は黙らせてくれますし、聞きたいときはちゃんと答えてくれます。\n\n結果がどうこうより、月に2回ここに来る時間があること自体が助かっています。&quot;},{&quot;name&quot;:&quot;Y様&quot;,&quot;age&quot;:&quot;60代&quot;,&quot;job&quot;:&quot;主婦&quot;,&quot;photo&quot;:&quot;https://liteword-assets.bigi-ishikawa.workers.dev/t/sec/km_voice_02.webp&quot;,&quot;alt&quot;:&quot;60代の方&quot;,&quot;excerpt&quot;:&quot;年齢のことで気後れしていましたが、同じくらいの方が多くて安心しました。&quot;,&quot;text&quot;:&quot;年齢のことで気後れしていましたが、同じくらいの方が多くて安心しました。\n\n若い方ばかりだったらどうしようと思っていたのですが、待合で一緒になるのは同年代の方ばかりです。\n\n「この年からでも意味がありますか」と最初に聞いたとき、「変わり方は人それぞれなので、3か月続けてみてから決めましょう」と言われました。断言されなかったのがかえって信用できました。&quot;}]" data-font-settings="{&quot;nameFontSet&quot;:&quot;&quot;,&quot;nameFontWeight&quot;:&quot;600&quot;,&quot;excerptFontSet&quot;:&quot;&quot;,&quot;excerptFontWeight&quot;:&quot;400&quot;}"><div class="inner" style="--paid-block-voice-3-max-width:1120px;--lw-voice-card-bg:#ffffff;--lw-voice-name-color:#5d2f38;--lw-voice-excerpt-color:#3a3336;--lw-voice-meta-color:#645b5e;--color-btn-bg:#9c5f68;--color-btn-text:#ffffff"><div class="swiper voice-swiper"><div class="swiper-wrapper"></div><div class="swiper-pagination"></div></div></div><div class="swiper-button-prev"></div><div class="swiper-button-next"></div><div class="voice-modal paid-block-voice-3-modal"><div class="modal-overlay"></div><div class="modal-content"><button class="modal-close"><svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><line x1="18" y1="6" x2="6" y2="18"></line><line x1="6" y1="6" x2="18" y2="18"></line></svg></button><div class="modal-body"><div class="modal-photo"><img src="" alt=""/></div><h3 class="modal-name" data-lw_font_set="" style="font-weight:600"></h3><p class="modal-meta"></p><div class="modal-text" data-lw_font_set="" style="font-weight:400"></div></div></div></div><script type="text/javascript">
(function(){
    var _sc = document.currentScript;
    var _root = ( _sc && _sc.closest ) ? _sc.closest(".paid-block-voice-3") : null;
    if ( !_root ) _root = document.querySelector(".paid-block-voice-3:not([data-lw-init])");
    if ( !_root ) return;
    _root.setAttribute("data-lw-init","1");
    if ( !_root.id ) _root.id = "paid-block-voice-3-" + Math.random().toString(36).slice(2,10);
    const selector = "#" + _root.id;
    const section = _root;

    // データを取得
    const voiceData = JSON.parse(section.getAttribute('data-voices'));
    const fontSettings = JSON.parse(section.getAttribute('data-font-settings'));

    // ========== HTML生成 ==========
    function generateHTML() {
        const swiperWrapper = section.querySelector('.swiper-wrapper');
        if (!swiperWrapper) return;

        const slidesHTML = voiceData.map((voice, index) => `
            <div class="swiper-slide">
                <div class="voice-card" data-voice-id="${index}">
                    <div class="photo">
                        <img loading="lazy" src="${voice.photo}" alt="${voice.alt || voice.name}">
                    </div>
                    <h3 
                        class="name" 
                        data-lw_font_set="${fontSettings.nameFontSet}"
                        style="font-weight: ${fontSettings.nameFontWeight}"
                    >${voice.name}</h3>
                    ${voice.age || voice.job ? '<p class="meta">' + (voice.age || '') + ' / ' + (voice.job || '') + '</p>' : ''}
                    <p 
                        class="excerpt"
                        data-lw_font_set="${fontSettings.excerptFontSet}"
                        style="font-weight: ${fontSettings.excerptFontWeight}"
                    >${voice.excerpt}</p>
                    <div class="more-btn">続きを読む</div>
                </div>
            </div>
        `).join('');

        swiperWrapper.innerHTML = slidesHTML;
    }

    // ========== Swiper初期化 ==========
    const MAX_RETRY = 30;
    let retry = 0;

    const initSwiper = () => {
        if (typeof Swiper === "undefined") return false;
        const swiperEl = section.querySelector('.voice-swiper');
        if (!swiperEl) return false;
        const already = swiperEl.swiper;
        if (already) return true;

        new Swiper(swiperEl, {
            slidesPerView: 1,
            spaceBetween: 20,
            loop: true,
            speed: 600,
            autoplay: {
                delay: 5000,
                disableOnInteraction: false
            },
            observer: true,
            observeParents: true,
            
            pagination: {
                el: selector + " .swiper-pagination",
                clickable: true
            },
            
            navigation: {
                nextEl: selector + " .swiper-button-next",
                prevEl: selector + " .swiper-button-prev"
            },
            breakpoints: {
                600: {
                    slidesPerView: 2,
                    spaceBetween: 24,
                },
                900: {
                    slidesPerView: 3,
                    spaceBetween: 30,
                },
            },
        });

        section.classList.remove("init-hide");
        return true;
    };

    // ========== モーダル処理 ==========
    function initModal() {
        // ★ 既にbody直下に移動済みかチェック（複数ブロック対応）
        let modal = document.querySelector('.paid-block-voice-3-modal[data-for-block="' + section.id + '"]');

        if (!modal) {
            // まだ移動していない場合、セクション内から取得
            modal = section.querySelector('.paid-block-voice-3-modal');
            if (!modal) return;

            // ★ モーダルをbody直下に移動（他ブロックのz-index影響を回避）
            document.body.appendChild(modal);
            modal.setAttribute('data-for-block', section.id);
        }

        const closeBtn = modal.querySelector('.modal-close');
        const overlay = modal.querySelector('.modal-overlay');

        // カードクリックでモーダル表示
        section.addEventListener('click', function(e) {
            const card = e.target.closest('.voice-card');
            if (!card) return;

            const voiceId = parseInt(card.getAttribute('data-voice-id'));
            const data = voiceData[voiceId];
            
            if (data) {
                modal.querySelector('.modal-photo img').src = data.photo;
                modal.querySelector('.modal-photo img').alt = data.alt || data.name;
                modal.querySelector('.modal-name').textContent = data.name;
                const modalMeta = modal.querySelector('.modal-meta');
                if (data.age || data.job) {
                    modalMeta.textContent = `${data.age || ''} / ${data.job || ''}`;
                    modalMeta.style.display = '';
                } else {
                    modalMeta.style.display = 'none';
                }
                modal.querySelector('.modal-text').textContent = data.text;
                
                modal.classList.add('active');
                document.body.style.overflow = 'hidden';
            }
        });

        // モーダルを閉じる
        function closeModal() {
            modal.classList.remove('active');
            document.body.style.overflow = '';
        }

        closeBtn.addEventListener('click', closeModal);
        overlay.addEventListener('click', closeModal);

        // ESCキーで閉じる
        document.addEventListener('keydown', function(e) {
            if (e.key === 'Escape' && modal.classList.contains('active')) {
                closeModal();
            }
        });
    }

    // ========== 初期化実行 ==========
    // 1. HTML生成
    generateHTML();

    // 2. Swiper初期化（複数トリガー）
    document.addEventListener("DOMContentLoaded", initSwiper, { once: true });
    window.addEventListener("lw:swiperReady", initSwiper, { once: true });

    const timer = setInterval(() => {
        if (initSwiper() || ++retry >= MAX_RETRY) clearInterval(timer);
    }, 150);

    setTimeout(() => {
        const el = document.querySelector(selector);
        if (el) el.classList.remove("init-hide");
    }, 5000);

    // 3. モーダル初期化
    initModal();
})();
        </script><noscript><style>.paid-block-voice-3{opacity:1!important}</style></noscript></div>
